check_no = #{checkNo}, check_date = #{checkDate}, status = #{status}, audit_by = #{auditBy}, audit_time = #{auditTime}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
